      { h: '几张容易误读的感情牌', p: '恋人不一定是新恋情，常常是「你必须做一次价值选择」；死神不一定是分手，常是「关系形态要变了」，比如从情侣变成亲人般的伙伴；恶魔不一定是第三者，多半是「你舍不得的是投入的时间」；塔不一定是撕破脸，常常是一次把话说开的爆发；隐者不一定是不爱了，可能只是需要自己的空间。把这些说清楚，你就不会用塔罗吓唬人。' }
