    quiz: [
      { q: '圣杯四的核心情绪是？', options: ['极度悲伤', '厌倦与不满足，错过眼前递来的新机会', '狂喜', '愤怒'], answer: 1, why: '他盯着递来的第四只杯却没接，是稳定后的倦怠。' },
      { q: '宝剑六的画面与含义是？', options: ['激烈战斗', '渡船离开风浪，驶向平静水域', '彻底失败', '独自庆祝'], answer: 1, why: '宝剑六是疗愈与转换，离开动荡前往平静。' },
      { q: '五号牌的共同解药是？', options: ['立刻忘掉', '看见还剩下的部分，而不是只盯着失去的', '换牌阵重抽', '等待别人来救'], answer: 1, why: '五的疗愈起点是把注意力从损失转向剩余。' }
    ],
    keywords: ['数字四', '数字五', '数字六', '稳定']
