      { h: '侍从的两面：新鲜 vs 不成熟', p: '侍从最大的优点是新鲜——热情、好奇、愿意从零学；最大的问题是浅——容易半途而废、说得多做得少、对困难估计不足。所以侍从牌给的建议常常是「可以开始，但别指望一次就成」或者「把自己当学生，多问多听」。逆位则是消息迟到、说了不做、或者因为怕被看轻而不肯承认自己是新手。' }
