      { h: '三张时间流：过去 / 现在 / 未来', p: '三张牌是最万能的日常牌阵。位置依次是过去（这件事的起因与来路）、现在（当下的真实状况）、未来（按现在这样走下去会到哪）。解读顺序有个小技巧：从「现在」开始读，因为它最实在；再看「过去」找原因；最后看「未来」给方向，并且一定要加上一句「如果你想改变这个走向，可以……」。这样三张牌就有了因果，而不是三句孤立的牌义。' }
