      { h: '十张整合：讲一个故事而不是念十段', p: '整合的方法是：先找主角——十张里那张大牌或宫廷牌往往就是主角，故事的视角围绕它展开；再找转折——塔、死神、命运之轮、战车这类牌就是情节的转折点；最后找落点——第十张加第六张决定结论。讲的时候控制在三段：第一段讲「事情本来是怎么回事」（1-5 张），第二段讲「接下来会发生什么」（6-9 张），第三段讲「所以你可以怎么做」（第 10 张 + 建议）。全程不超过五分钟，超过就说明你在念牌义。' }
