    upright: '目标明确，冲就能赢。这张牌是塔罗里最强的推进力之一：它意味着方向已经清楚，现在拼的是执行与坚持。感情上是主动推进比等对方表态有效；工作上是到了全力冲刺的阶段。它也可能指一次出行、搬迁、或快速推进的事务。',
    reversed: '方向错了还在猛踩油门，或者内耗严重——两股力量互相拉扯，车在原地轰油门。也可能是「赢了但不知道为什么赢」，缺乏可持续的方向。',
    symbol: '勇士披着缀满星点的斗篷，头戴象征心智的星冠；车上没有缰绳，说明他靠意志与方向感驾驭，而不是靠硬拉；前方两只狮身人面兽一黑一白，是被驾驭的对立力量；车上的方形与翅膀、肩上的新月，都在讲「把矛盾的力量朝同一个方向拉」。',
    life: '感情上：「主动推进比等对方表态更有效，但别用强——方向一致比速度重要」。工作上：「这个项目到了必须全力冲的阶段，别再犹豫，先定终点再谈速度」。决策上：「先写清楚你要到哪，再问自己现在做的这件事有没有朝那个方向走。」',
    pair: '战车+权杖八＝进度极快，准备好接住。战车+宝剑五＝赢了但代价不小，赢了也未必开心。战车+节制＝别只顾冲，节奏要能撑得住。'
