    upright: '你比你以为的更有韧性，而赢的方式不是硬碰硬。这张牌讲的是「温柔的力量」：驯服一头狮子靠的不是打，是摸它的头。它常出现在你需要压住脾气、耐心磨一件事、或者面对一个强势的人时。感情上是先稳住自己再谈事；工作上是慢慢磨、别撕破脸。',
