    kw: ['灵感', '火花', '开端', '冲动', '机会'],
    upright: '一团新的热情冒出来了：一个让你眼睛一亮的想法、邀约或机会。它的能量很足，但还很原始，需要你立刻做点什么把它接住。工作上是新项目启动、创业念头；感情上是心动、想靠近的冲动。别只停在兴奋里，先做最小的一步。',
