    symbol: '男人抱着十根权杖弯腰前行，权杖遮住了他的头和视线，远处是城镇。重点在于：目的地就在眼前，而他看不见路——这些杖是他自己揽下的，也完全可以放下几根。整张牌的疲惫是自找的，不是被强加的。',
