    symbol: '大一点的孩子把杯中的花递给小一点的孩子，六只杯里都盛着白花，背景是熟悉的宅院与守卫。两个孩子都是金发、姿态温柔——这张牌的画面刻意做成「记忆中的样子」：柔和、安全、没有冲突。',
    life: '感情上：「你怀念的不是那个人，是那时被好好对待的感觉——这个感觉值得你现在就去创造」。工作上：「回到你最初为什么喜欢这件事，答案就在那里」。决策上：「回忆可以参考，但别拿过去的标准套现在。」',
    pair: '圣杯六+圣杯二＝旧情或旧友重新走近。圣杯六+隐者＝回到过去找答案，但别住下来。圣杯六+审判＝旧事重提并做一次清算。'
