    symbol: '人背对观众站在云雾中，面前悬浮着七只杯子，每只杯里是不同的幻象：桂冠、人头、城堡、珠宝、蛇、龙、裹着布的影子。杯子浮在云上是关键：它们不在地上，说明都还不是现实——这张牌是选择的眩晕，不是机会的丰盛。',
