    life: '感情上：「你想要的回应会有，而且比你期待的还好一点」。工作上：「这次的结果会让你满意，记得把它写进简历或复盘」。决策上：「允许自己高兴一下，别立刻给自己加新目标——享受也是生产力。」',
    pair: '圣杯九+星币九＝既有满足又有实在收获。圣杯九+太阳＝公开的好消息与快乐。圣杯九+圣杯四＝物质满足但心里空，注意区分。'
